exercises.solution:
let balance = 100;
let locked = false;
function withLock(fn) {
  if (locked) return;
  locked = true;
  fn();
  locked = false;
}
withLock(() => { balance -= 60; });
withLock(() => { balance -= 60; });
console.log('locked result: ' + balance);

